        }
    }

    suspend fun sendGensetCheck(
        context: Context,
        statusGenset: String,
        oilCheck: String,
        fuelInfo: String,
        officer: String,
        note: String,
        address: String,
        coords: String,
        photoFisik: File,
        photoHse: File?,
        videoFile: File?
    ): Pair = withContext(Dispatchers.IO) {
        try {
            val b64Fisik = encodeFileToBase64(photoFisik)
            val b64Hse = if (photoHse != null && photoHse.exists()) encodeFileToBase64(photoHse) else null
            val b64Video = if (videoFile != null && videoFile.exists()) encodeFileToBase64(videoFile) else null

            val json = JSONObject().apply {
                put("action", "genset")
                put("sessionToken", getSessionToken(context))
                put("idempotencyKey", buildIdempotencyKey(photoFisik))
                put("statusGenset", statusGenset)
                put("oilCheck", oilCheck)
                put("fuelInfo", fuelInfo)
                put("officerName", officer)
                put("note", note)
                put("address", address)
                put("coordinates", coords)
                put("fileName", photoFisik.name)
                put("imageBase64", b64Fisik)
                if (b64Hse != null) put("hseDocBase64", b64Hse)
                if (b64Video != null) put("videoBase64", b64Video)
            }
            postJson(getEndpointUrl(context), json)
        } catch (e: Exception) {
